function GlossaryPage({entries,languages,source,target,language,editing,onSource,onTarget,onLanguage,onSubmit,onEdit,onDelete,onCancel,tx}:any){return <Card className="glossary-page form-card"><div className="section-heading"><div><h2><BookOpen size={22}/>{tx('Çeviri Sözlüğü','Translation glossary')}</h2></div><span className="muted">{entries.length} {tx('terim','terms')}</span></div><form className="glossary-form" onSubmit={onSubmit}><label>{tx('Kaynak terim','Source term')}<input required maxLength={120} value={source} onChange={e=>onSource(e.target.value)} placeholder={tx('Örn. program adı','e.g. program name')}/></label><label>{tx('Tercih edilen karşılık','Preferred translation')}<input required maxLength={120} value={target} onChange={e=>onTarget(e.target.value)} placeholder={tx('Sözlükte kullanılacak karşılık','Preferred translated term')}/></label><label>{tx('Hedef dil','Target language')}<Select value={language} onChange={e=>onLanguage(e.target.value)}>{languages.map((item:Choice)=><option key={item.key} value={item.key}>{item.label}</option>)}</Select></label><div className="glossary-form-actions"><ButtonX className="primary" type="submit"><Plus size={15}/>{editing===null?tx('Terim ekle','Add term'):tx('Değişikliği kaydet','Save changes')}</ButtonX>{editing!==null&&<ButtonX type="button" onClick={onCancel}>{tx('Vazgeç','Cancel')}</ButtonX>}</div></form><div className="glossary-list">{entries.map((entry:GlossaryEntry,index:number)=><div className="glossary-row" key={entry.language+'|'+entry.source}><div className="glossary-pair"><strong>{entry.source}</strong><ArrowRight size={15}/><span>{entry.target}</span><small>{entry.language}</small></div><div className="glossary-row-actions"><ButtonX aria-label={tx('Terimi düzenle','Edit term')} onClick={()=>onEdit(index)}><Settings size={14}/>{tx('Düzenle','Edit')}</ButtonX><ButtonX aria-label={tx('Terimi kaldır','Delete term')} onClick={()=>onDelete(index)}><Trash2 size={14}/>{tx('Sil','Delete')}</ButtonX></div></div>)}{entries.length===0&&<div className="empty"><BookOpen size={30}/><p>{tx('Bu profilde henüz sözlük terimi yok. İlk terimi yukarıdan ekleyin.','This profile has no glossary terms yet. Add the first term above.')}</p></div>}</div></Card>;}

const pending=new Map<string,{resolve:(v:any)=>void,reject:(e:Error)=>void,timer:ReturnType<typeof setTimeout>}>();
let sequence=0;
function command(command:string,args:Record<string,unknown>={}):Promise<any>{return new Promise((resolve,reject)=>{const id=String(++sequence);if(!window.chrome?.webview){reject(new Error('Masaüstü bağlantısı yok. Bu ekran tarayıcı önizlemesidir.'));return;}const timer=setTimeout(()=>{if(pending.delete(id))reject(new Error('İşlem yanıt vermedi. Bağlantıyı kontrol edin; yeniden denemeden önce işlemin tamamlanıp tamamlanmadığını kontrol edin.'));},command==='login'||command.startsWith('profile')?600000:120000);pending.set(id,{resolve,reject,timer});try{window.chrome.webview.postMessage({id,command,...args});}catch(error){clearTimeout(timer);pending.delete(id);reject(error instanceof Error?error:new Error(String(error)));}});}
 const ButtonX=({children,onClick,disabled=false,className='',...rest}:any)=><Button variant="glass" effect="none" disabled={disabled} className={'control '+className} onClick={onClick} {...rest}>{children}</Button>;


const slotReadyForControl=(slot:Slot)=>!!slot.input&&slot.ready&&!slot.translating;
function controlCards(s:State){
 const added=new Set(s.controlCardOrder);
 return {
  slots:s.slots.filter(slot=>slotReadyForControl(slot)&&added.has('slot-'+slot.number)),
  lists:s.playlist.lists.filter(list=>list.count>0&&added.has('playlist-'+list.id))
 };
}

function ControlMembershipButton({id,added,run,tx}:{id:string,added:boolean,run:(name:string,args?:Record<string,unknown>)=>Promise<any>,tx:(tr:string,en:string)=>string}){
 return <ButtonX onClick={()=>run('controlSetCardVisibility',{cardId:id,visible:!added})}>
  {added?tx('Control’den çıkar','Remove from Control'):tx('Control’e ekle','Add to Control')}
 </ButtonX>;
}

